class Point {
	constructor(x=0, y=0){
		this.x = Math.round(x);
		this.y = Math.round(y);
	}

	equalTo(p) {
		return p.x === this.x && p.y === this.y
	}

	move(deltaX, deltaY) {
		this.x = Math.round(this.x + deltaX);
		this.y = Math.round(this.y + deltaY);
	}

	clone() {
		return new Point(this.x, this.y);
	}

	save() {
		return {
			x: Math.round(this.x),
			y: Math.round(this.y)
		}
	}
}

export default Point;
